CREATE OR REPLACE FUNCTION public.touchline_club_commit_acquisition(p_user_id uuid, p_season_id uuid, p_expected_revision bigint, p_next jsonb, p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
 SET lock_timeout TO '5s'
AS $function$
declare
  v_current public.touchline_club_collections%rowtype;
  v_prior public.touchline_club_collection_operations%rowtype;
  v_player jsonb;
  v_price numeric;
  v_position_limit int;
  v_slot_limit int;
  v_geometry jsonb;
  v_key text := p_command->>'idempotencyKey';
begin
  perform public.touchline_club_lock_open_round(p_season_id);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('touchline-fantasy-subscription:' || p_user_id::text,0));
  select * into v_current from public.touchline_club_collections
    where user_id=p_user_id and season_id=p_season_id for update;
  if not found then raise exception 'CLUB_COLLECTION_REQUIRED'; end if;
  select * into v_prior from public.touchline_club_collection_operations
    where user_id=p_user_id and season_id=p_season_id and idempotency_key=v_key;
  if found then
    if v_prior.command is distinct from p_command then raise exception 'CLUB_IDEMPOTENCY_CONFLICT'; end if;
    return v_current.state;
  end if;
  if p_expected_revision is distinct from v_current.revision
    or (p_command->>'expectedRevision')::bigint is distinct from v_current.revision then
    raise exception 'CLUB_STALE_REVISION';
  end if;
  if not exists(select 1 from public.touchline_fantasy_entitlements e
    where e.user_id=p_user_id and e.entitlement_key='fantasy_access' and e.status='active'
    and e.plan_key=v_current.state->>'plan'
    and (e.current_period_start is null or e.current_period_start <= clock_timestamp())
    and (e.current_period_end is null or e.current_period_end > clock_timestamp())) then
    raise exception 'CLUB_ACCESS_REQUIRED';
  end if;
  -- Reuse the published round window. Never infer a final whistle here.
  if not public.touchline_club_market_is_open(p_season_id) then raise exception 'CLUB_MARKET_CLOSED';
  end if;
  if p_next->>'seasonId' is distinct from p_season_id::text
    or (p_next-array['players','receipts','revision','balanceEur']) is distinct from (v_current.state-array['players','receipts','revision','balanceEur'])
    or p_next->>'plan' is distinct from v_current.state->>'plan'
    or p_next->'coach' is distinct from v_current.state->'coach'
    or (p_next->>'revision')::bigint is distinct from v_current.revision+1
    or jsonb_array_length(p_next->'players') is distinct from jsonb_array_length(v_current.state->'players')+1
    or jsonb_array_length(p_next->'receipts') is distinct from jsonb_array_length(v_current.state->'receipts')+1 then
    raise exception 'CLUB_INVALID_TRANSITION';
  end if;
  v_player := p_next->'players'->-1;
  if (p_next->'players') - (jsonb_array_length(p_next->'players')-1) is distinct from v_current.state->'players'
    or (p_next->'receipts') - (jsonb_array_length(p_next->'receipts')-1) is distinct from v_current.state->'receipts'
    or v_player->>'playerId' is distinct from p_command->>'playerId'
    or v_player->>'area' is distinct from p_command->>'area'
    or v_player->'slot' is distinct from p_command->'slot' then
    raise exception 'CLUB_INVALID_TRANSITION';
  end if;
  v_price := (v_player->>'valueEur')::numeric;
  if v_price is null or v_price <= 0 or trunc(v_price) <> v_price
    or (p_next->>'balanceEur')::numeric is distinct from (v_current.state->>'balanceEur')::numeric-v_price then
    raise exception 'CLUB_INVALID_DEBIT';
  end if;
  if not exists(select 1 from public.touchline_card_publications p
    join public.football_players f on f.id=p.player_id
    join public.football_player_market_values m on m.id=p.market_value_id and m.player_id=p.player_id
    where p.player_id=(v_player->>'playerId')::uuid and p.publication_status='published'
      and f.current_club_id=(v_player->>'clubId')::uuid
      and m.status='verified' and m.confidence='verified' and m.market_value_eur=v_price) then
    raise exception 'CLUB_OFFER_UNAVAILABLE';
  end if;
  if p_next->'receipts'->-1 is distinct from jsonb_build_object('key',v_key,
    'playerId',v_player->>'playerId','area',v_player->>'area','slot',v_player->'slot',
    'valueEur',v_price,'revision',v_current.revision+1) then raise exception 'CLUB_RECEIPTS_INVALID'; end if;
  v_slot_limit:=case v_player->>'area' when 'starters' then 11 when 'reserves' then 9 when 'outside' then 15 end;
  if v_slot_limit is null or jsonb_typeof(v_player->'slot') is distinct from 'number'
    or (v_player->>'slot')::numeric<>trunc((v_player->>'slot')::numeric)
    or (v_player->>'slot')::int<0 or (v_player->>'slot')::int>=v_slot_limit then raise exception 'CLUB_ROSTER_INVALID'; end if;
  v_position_limit:=case v_player->>'position' when 'GK' then 3 when 'CB' then 6 when 'RB' then 3 when 'LB' then 3
    when 'DM' then 5 when 'MID' then 5 when 'RW' then 3 when 'LW' then 3 when 'CF' then 4 end;
  if v_position_limit is null or (select count(*) from jsonb_array_elements(p_next->'players') p
    where p->>'position'=v_player->>'position')>v_position_limit then raise exception 'CLUB_POSITION_FULL'; end if;
  if (select count(*) from jsonb_array_elements(p_next->'players') p
    where p->>'clubId'=v_player->>'clubId' and not p ? 'transferException')>3 then raise exception 'CLUB_TEAM_LIMIT'; end if;
  if exists(select 1 from jsonb_array_elements(v_current.state->'players') p
    where p->>'playerId'=v_player->>'playerId' or (p->>'area'=v_player->>'area' and p->'slot'=v_player->'slot')) then
    raise exception 'CLUB_ALREADY_OWNED_OR_SLOT_OCCUPIED';
  end if;
  if v_player ? 'transferException' then raise exception 'CLUB_INVALID_TRANSITION'; end if;
  if v_player->>'area'='starters' then
    select geometry into v_geometry from public.touchline_formation_geometry_versions
      where formation_code=p_next->>'formationCode' and status='published' order by geometry_version desc limit 1;
    if v_geometry is null or jsonb_array_length(v_geometry->'slots')<>11 then raise exception 'CLUB_FORMATION_INVALID'; end if;
    if not coalesce((v_geometry->'slots'->((v_player->>'slot')::int)->'allowedPositions') ?
      (case v_player->>'position' when 'GK' then 'goalkeeper' when 'CB' then 'centre-back'
        when 'RB' then 'right-back' when 'LB' then 'left-back' when 'DM' then 'defensive-midfield'
        when 'MID' then 'midfield' when 'RW' then 'attacker' when 'LW' then 'attacker'
        when 'CF' then 'centre-forward' end),false) then raise exception 'CLUB_SLOT_POSITION_INVALID'; end if;
  end if;
  update public.touchline_club_collections set state=p_next, revision=revision+1, updated_at=now()
    where user_id=p_user_id and season_id=p_season_id;
  insert into public.touchline_club_collection_operations(user_id,season_id,idempotency_key,command,revision)
    values(p_user_id,p_season_id,v_key,p_command,v_current.revision+1);
  return p_next;
end;
$function$

CREATE OR REPLACE FUNCTION public.touchline_club_project_lineup(p_user_id uuid, p_gameweek_id uuid, p_selected_coach_id text, p_formation_code text, p_selections jsonb, p_action text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gameweek public.touchline_fantasy_gameweeks%rowtype;
  v_config public.touchline_fantasy_configs%rowtype;
  v_user_gameweek_id uuid;
  v_geometry jsonb;
  v_count integer;
  v_invalid integer;
  v_total bigint;
  v_max_club integer;
  v_collection public.touchline_club_collections%rowtype;
  v_plan_key text;
  v_effective_budget bigint;
  v_allowed_team_ids text[];
begin
  if p_action not in ('draft', 'confirm') then raise exception 'TL_FANTASY_ACTION_INVALID'; end if;
  if length(btrim(coalesce(p_idempotency_key, ''))) not between 8 and 160 then raise exception 'TL_FANTASY_IDEMPOTENCY_REQUIRED'; end if;
  if jsonb_typeof(p_selections) <> 'array' then raise exception 'TL_FANTASY_SELECTIONS_INVALID'; end if;
  if p_selected_coach_id is null or not (p_selected_coach_id = any(array[
    '307','455907','29710','255','37679','511','95','37732840','455355','515',
    '74546','270','460535','19960388','107439','645','523911','51518','529482','127889'
  ]::text[])) then raise exception 'TL_FANTASY_COACH_INVALID'; end if;
  if not public.touchline_fantasy_entitlement_is_active(p_user_id) then raise exception 'TL_FANTASY_ENTITLEMENT_REQUIRED'; end if;

  -- Round synchronization belongs to the outer wrapper.
  perform pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text || ':' || p_gameweek_id::text, 0));
  select * into v_gameweek from public.touchline_fantasy_gameweeks where id = p_gameweek_id for update;
  if v_gameweek.id is null then raise exception 'TL_FANTASY_GAMEWEEK_NOT_FOUND'; end if;
  if v_gameweek.state <> 'MARKET_OPEN' or clock_timestamp() >= v_gameweek.locks_at then raise exception 'TL_FANTASY_GAMEWEEK_LOCKED'; end if;
  select * into v_config from public.touchline_fantasy_configs
   where competition_id = v_gameweek.competition_id and season_id = v_gameweek.season_id and status = 'active';
  if v_config.id is null then raise exception 'TL_FANTASY_CONFIG_NOT_FOUND'; end if;
  select * into v_collection from public.touchline_club_collections
    where user_id=p_user_id and season_id=v_gameweek.season_id for update;
  if not found then raise exception 'CLUB_COLLECTION_REQUIRED'; end if;
  if v_collection.state->'coach'->>'id' is distinct from p_selected_coach_id
    or v_collection.state->>'formationCode' is distinct from p_formation_code then
    raise exception 'CLUB_LINEUP_OWNERSHIP_MISMATCH'; end if;
  -- Original XI budget is not a second wallet. Its scoring snapshot records
  -- the already-funded collection envelope, including coach debit separately.
  v_effective_budget := (v_collection.state->>'balanceEur')::bigint +
    (select coalesce(sum((p->>'valueEur')::bigint),0) from jsonb_array_elements(v_collection.state->'players') p);
  if exists(select 1 from jsonb_array_elements(v_collection.state->'players') p
    where not (p ? 'transferException') group by p->>'clubId' having count(*)>3) then
    raise exception 'CLUB_TEAM_LIMIT'; end if;
  if jsonb_array_length(p_selections)<>(select count(*) from jsonb_array_elements(v_collection.state->'players') p where p->>'area'='starters')
    or exists(select 1 from jsonb_array_elements(p_selections) requested
      where not exists(select 1 from jsonb_array_elements(v_collection.state->'players') p
        where p->>'playerId'=requested->>'playerId' and p->>'area'='starters')) then
    raise exception 'CLUB_LINEUP_OWNERSHIP_MISMATCH'; end if;

  select entitlement.plan_key into v_plan_key
  from public.touchline_fantasy_entitlements entitlement
  where entitlement.user_id = p_user_id
    and entitlement.entitlement_key = 'fantasy_access'
    and entitlement.status = 'active'
    and (entitlement.current_period_start is null or entitlement.current_period_start <= clock_timestamp())
    and (entitlement.current_period_end is null or entitlement.current_period_end > clock_timestamp())
  for share;
  if not found then raise exception 'TL_FANTASY_ENTITLEMENT_REQUIRED'; end if;
  if v_plan_key is null or v_plan_key not in ('beta', 'standard', 'pro', 'master', 'vip') then
    raise exception 'TL_FANTASY_PLAN_INVALID';
  end if;
  v_effective_budget := case
    when v_plan_key = 'beta' then 50000000
    when v_plan_key = 'standard' then 400000000
    when v_plan_key = 'pro' then 650000000
    when v_plan_key = 'master' then 850000000
    when v_plan_key = 'vip' then 1000000000 end;
  v_allowed_team_ids := case when v_plan_key = 'beta' then array['22','117','116','52']::text[] else null end;
  select geometry into v_geometry from public.touchline_formation_geometry_versions
   where formation_code = p_formation_code and status = 'published'
   order by geometry_version desc limit 1;
  if v_geometry is null then raise exception 'TL_FANTASY_FORMATION_NOT_PUBLISHED'; end if;

  select count(*), count(distinct item."playerId"), count(distinct item."slotId")
    into v_count, v_invalid, v_max_club
  from jsonb_to_recordset(p_selections) as item("playerId" text, "slotId" text);
  if v_count > 11 or v_count <> v_invalid or v_count <> v_max_club then raise exception 'TL_FANTASY_SELECTION_DUPLICATE_OR_OVERSIZED'; end if;
  if p_action = 'confirm' and v_count <> 11 then raise exception 'TL_FANTASY_XI_REQUIRES_11'; end if;

  with requested as (
    select item."playerId"::uuid player_id, item."slotId" slot_id
    from jsonb_to_recordset(p_selections) as item("playerId" text, "slotId" text)
    where item."playerId" ~* '^[0-9a-f-]{36}$' and length(btrim(item."slotId")) between 1 and 24
  ), eligible as (
    select distinct on (player.id) player.id player_id, membership.club_id, value.market_value_eur,
      public.touchline_fantasy_position_bucket(coalesce(membership.detailed_position, membership.position, player.detailed_position, player.position)) position_bucket
    from public.touchline_card_publications publication
    join public.football_player_market_values value on value.id = publication.market_value_id
    join public.football_players player on player.id = publication.player_id
    join public.football_squad_members membership on membership.id = publication.current_membership_id
    where publication.publication_status = 'published'
      and value.status = 'verified' and value.confidence = 'verified' and value.market_value_eur is not null
      and membership.status = 'active' and membership.club_id = player.current_club_id
      and (v_plan_key is distinct from 'beta' or exists (
        select 1 from public.football_clubs policy_club
        where policy_club.id = membership.club_id
          and policy_club.provider = 'sportmonks'
          and policy_club.provider_team_id::text = any(v_allowed_team_ids)
      ))
    order by player.id, publication.published_at desc nulls last
  ), resolved as (
    select requested.*, eligible.club_id, eligible.market_value_eur, eligible.position_bucket,
      slot.value ->> 'role' formation_role,
      exists (select 1 from jsonb_array_elements_text(coalesce(slot.value -> 'allowedPositions', '[]'::jsonb)) allowed(value)
        where allowed.value = eligible.position_bucket) position_allowed
    from requested left join eligible on eligible.player_id = requested.player_id
    left join lateral (select value from jsonb_array_elements(v_geometry -> 'slots') candidate(value)
      where candidate.value ->> 'id' = requested.slot_id limit 1) slot on true
  )
  select count(*) filter (where club_id is null or market_value_eur is null or position_bucket is null
      or formation_role is null or not position_allowed) + (v_count - count(*)),
    coalesce(sum(market_value_eur), 0),
    coalesce((select max(n) from (select club_id, count(*) n from resolved where club_id is not null group by club_id) clubs), 0)
  into v_invalid, v_total, v_max_club from resolved;
  if v_invalid > 0 then raise exception 'TL_FANTASY_SELECTION_INELIGIBLE'; end if;

  if v_collection.state->>'plan' is distinct from v_plan_key then raise exception 'CLUB_PLAN_MISMATCH'; end if;
  v_effective_budget := (v_collection.state->>'balanceEur')::bigint +
    (select coalesce(sum((p->>'valueEur')::bigint),0) from jsonb_array_elements(v_collection.state->'players') p);
  if v_effective_budget is not null and v_total > v_effective_budget then raise exception 'TL_FANTASY_BUDGET_EXCEEDED'; end if;
  -- Full collection quota was validated above, including non-transferable exceptions.

  insert into public.touchline_fantasy_user_gameweeks (
    user_id, gameweek_id, selected_coach_id, formation_code, state, budget_eur_snapshot, market_plan_key_snapshot,
    max_players_per_club_snapshot, total_market_value_eur, last_idempotency_key, confirmed_at
  ) values (
    p_user_id, p_gameweek_id, p_selected_coach_id, p_formation_code,
    case when p_action = 'confirm' then 'CONFIRMED' else 'DRAFT' end,
    v_effective_budget, v_plan_key, v_config.max_players_per_club, v_total, p_idempotency_key,
    case when p_action = 'confirm' then now() else null end
  ) on conflict (user_id, gameweek_id) do update set
    selected_coach_id = excluded.selected_coach_id, formation_code = excluded.formation_code,
    state = excluded.state, budget_eur_snapshot = excluded.budget_eur_snapshot,
    market_plan_key_snapshot = excluded.market_plan_key_snapshot,
    max_players_per_club_snapshot = excluded.max_players_per_club_snapshot,
    total_market_value_eur = excluded.total_market_value_eur,
    last_idempotency_key = excluded.last_idempotency_key, confirmed_at = excluded.confirmed_at
  returning id into v_user_gameweek_id;


  update public.touchline_fantasy_user_gameweeks set collection_revision_snapshot=v_collection.revision,
    collection_related_snapshot=(select coalesce(jsonb_agg(jsonb_build_object('playerId',p->>'playerId','area',p->>'area','slot',p->'slot')),'[]'::jsonb)
      from jsonb_array_elements(v_collection.state->'players') p where p->>'area' in ('starters','reserves'))
    where id=v_user_gameweek_id;
  delete from public.touchline_fantasy_user_gameweek_selections where user_gameweek_id = v_user_gameweek_id;
  insert into public.touchline_fantasy_user_gameweek_selections (
    user_gameweek_id, slot_id, slot_index, player_id, club_id, formation_role, position_bucket, market_value_eur
  )
  with requested as (
    select item."playerId"::uuid player_id, item."slotId" slot_id
    from jsonb_to_recordset(p_selections) as item("playerId" text, "slotId" text)
  ), eligible as (
    select distinct on (player.id) player.id player_id, membership.club_id, value.market_value_eur,
      public.touchline_fantasy_position_bucket(coalesce(membership.detailed_position, membership.position, player.detailed_position, player.position)) position_bucket
    from public.touchline_card_publications publication
    join public.football_player_market_values value on value.id = publication.market_value_id
    join public.football_players player on player.id = publication.player_id
    join public.football_squad_members membership on membership.id = publication.current_membership_id
    where publication.publication_status = 'published' and value.status = 'verified'
      and value.confidence = 'verified' and value.market_value_eur is not null
      and membership.status = 'active' and membership.club_id = player.current_club_id
      and (v_plan_key is distinct from 'beta' or exists (
        select 1 from public.football_clubs policy_club
        where policy_club.id = membership.club_id
          and policy_club.provider = 'sportmonks'
          and policy_club.provider_team_id::text = any(v_allowed_team_ids)
      ))
    order by player.id, publication.published_at desc nulls last
  )
  select v_user_gameweek_id, requested.slot_id, (slot.value ->> 'priority')::integer,
    requested.player_id, eligible.club_id, slot.value ->> 'role', eligible.position_bucket, eligible.market_value_eur
  from requested join eligible using (player_id)
  join lateral (select value from jsonb_array_elements(v_geometry -> 'slots') candidate(value)
    where candidate.value ->> 'id' = requested.slot_id limit 1) slot on true
  order by (slot.value ->> 'priority')::integer;

  insert into public.touchline_fantasy_audit_events (user_id, gameweek_id, event_type, idempotency_key, metadata)
  values (p_user_id, p_gameweek_id, case when p_action = 'confirm' then 'XI_CONFIRMED' else 'DRAFT_SAVED' end,
    p_idempotency_key, jsonb_build_object('selectionCount', v_count, 'formationCode', p_formation_code,
      'selectedCoachId', p_selected_coach_id, 'totalMarketValueEur', v_total))
  on conflict (idempotency_key) where idempotency_key is not null do nothing;

  return jsonb_build_object('ok', true, 'userGameweekId', v_user_gameweek_id,
    'state', case when p_action = 'confirm' then 'CONFIRMED' else 'DRAFT' end,
    'selectedCoachId', p_selected_coach_id, 'selectionCount', v_count,
    'totalMarketValueEur', v_total, 'budgetRemainingEur', case when v_effective_budget is null then null else v_effective_budget - v_total end);
end;
$function$
